#!/usr/bin/env python3
from __future__ import annotations

import json
from pathlib import Path


TASK_ID = "CSX-049_Q1"
EVENT_ID = "CSX-049"
TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = Path(__file__).resolve().parents[3]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

ANCHOR = "data/event_reports/event_reports_003_Locked_event_anchor_September_2021_Hurricane_Ida_rainfall_flooding_in_New_York_City.json"
REPORT = "data/event_reports/event_reports_002_Wikipedia_Northeast_Ida_effects.json"
ERA5 = "data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json"
GPM = "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json"
CHIRPS = "data/physical_hazard/physical_hazard_006_CHIRPS_daily_event_accumulated_precipitation.json"


def load_json(rel_path: str) -> dict:
    return json.loads((PACKAGE_DIR / rel_path).read_text(encoding="utf-8-sig"))


def round2(value: float) -> float:
    return round(float(value), 2)


def inclusive_days(start: str, end: str) -> int:
    from datetime import date

    start_date = date.fromisoformat(start)
    end_date = date.fromisoformat(end)
    return (end_date - start_date).days + 1


def report_flag_count(text: str) -> int:
    lower = text.lower()
    flags = [
        "shutting down numerous roads",
        "halting public transit",
        "cancelling hundreds of flights",
        "hundreds of cars",
        "high-water rescues",
        "flash flood emergencies",
    ]
    return sum(flag in lower for flag in flags)


def build_rubric() -> dict:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Final JSON and label",
                "points": 3,
                "description": "Returns the requested compact JSON and the high-contrast pluvial-flood label.",
                "partial_credit": "Partial credit for a recoverable JSON answer with a compatible but imprecise label.",
            },
            {
                "name": "Product maxima",
                "points": 4,
                "description": "Computes ERA5, GPM, and CHIRPS event-maximum precipitation correctly.",
                "partial_credit": "Partial credit for two correct maxima or minor rounding errors.",
            },
            {
                "name": "Concentration ratios",
                "points": 4,
                "description": "Computes all three max-to-mean ratios and recognizes that all exceed the threshold.",
                "partial_credit": "Partial credit for correct method with one product error.",
            },
            {
                "name": "Satellite peak agreement",
                "points": 3,
                "description": "Computes the GPM-CHIRPS maximum disagreement percent and applies the <= 5% test.",
                "partial_credit": "Partial credit for identifying close agreement without the exact percent.",
            },
            {
                "name": "Report flags",
                "points": 3,
                "description": "Counts the six report impact flags and uses them as report anchors.",
                "partial_credit": "Partial credit for at least four correct flags.",
            },
            {
                "name": "Diagnostic score",
                "points": 2,
                "description": "Applies all six decision tests and reports score_0_to_6 = 6.",
                "partial_credit": "Partial credit for one test error with the same broad conclusion.",
            },
            {
                "name": "Compact interpretation",
                "points": 1,
                "description": "Keeps the interpretation tied to the computed diagnostic score and avoids extra realized-loss accounting.",
                "partial_credit": "Partial credit for a longer but still numerically grounded interpretation.",
            },
        ],
    }


def build_output() -> dict:
    anchor = load_json(ANCHOR)
    report = load_json(REPORT)
    era5 = load_json(ERA5)["stats"]
    gpm = load_json(GPM)["stats"]
    chirps = load_json(CHIRPS)["stats"]

    event_window_days = inclusive_days(
        anchor["temporal_window"]["start_date"],
        anchor["temporal_window"]["end_date"],
    )
    precip_max = {
        "era5": round2(era5["precipitation_sum_mm_max"]),
        "gpm": round2(gpm["gpm_event_precip_mm_max"]),
        "chirps": round2(chirps["chirps_event_precip_mm_max"]),
    }
    max_to_mean = {
        "era5": round2(era5["precipitation_sum_mm_max"] / era5["precipitation_sum_mm_mean"]),
        "gpm": round2(gpm["gpm_event_precip_mm_max"] / gpm["gpm_event_precip_mm_mean"]),
        "chirps": round2(chirps["chirps_event_precip_mm_max"] / chirps["chirps_event_precip_mm_mean"]),
    }
    satellite_disagreement = round2(
        abs(gpm["gpm_event_precip_mm_max"] - chirps["chirps_event_precip_mm_max"])
        / ((gpm["gpm_event_precip_mm_max"] + chirps["chirps_event_precip_mm_max"]) / 2.0)
        * 100.0
    )
    flags = report_flag_count(report["extract"])
    tests = {
        "two_day_window": event_window_days == 2,
        "era5_max_ge10mm": precip_max["era5"] >= 10,
        "satellite_maxima_ge18mm": precip_max["gpm"] >= 18 and precip_max["chirps"] >= 18,
        "all_max_to_mean_ratios_ge5": all(value >= 5 for value in max_to_mean.values()),
        "report_flags_ge5": flags >= 5,
        "gpm_chirps_disagreement_le5pct": satellite_disagreement <= 5,
    }
    score = sum(tests.values())

    primary_gt = {
        "answer_label": "short_window_high_contrast_pluvial_flood_signature",
        "event_window_days": event_window_days,
        "precip_max_mm": precip_max,
        "max_to_mean_ratios": max_to_mean,
        "satellite_max_disagreement_percent": satellite_disagreement,
        "report_flag_count": flags,
        "score_0_to_6": score,
        "computed_interpretation": (
            "The two-day Ida record has concentrated precipitation maxima across products, close GPM-CHIRPS peak agreement, and six independent disruption flags."
        ),
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": "ida_nyc_pluvial_rainfall_concentration_diagnosis",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "key_values": {
            "decision_tests": tests,
            "thresholds": {
                "era5_max_mm": 10,
                "satellite_max_mm": 18,
                "max_to_mean_ratio": 5,
                "report_flag_count": 5,
                "satellite_disagreement_percent": 5,
            },
            "report_flag_phrases": [
                "road shutdowns",
                "public transit disruption",
                "flight cancellations",
                "stranded cars",
                "high-water rescues",
                "flash-flood emergency statements",
            ],
        },
        "rubric": build_rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [ANCHOR, REPORT, ERA5, GPM, CHIRPS],
        },
    }

def main() -> None:
    computed_gt = build_output()
    (TASK_DIR / "computed_gt.json").write_text(
        json.dumps(computed_gt, indent=2, ensure_ascii=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
